import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"技术决策框架","description":"","frontmatter":{"title":"技术决策框架","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/decision-framework.md","filePath":"frontend/decisions/decision-framework.md","lastUpdated":1785589115000}'),l={name:"frontend/decisions/decision-framework.md"};function i(o,t,h,n,s,u){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="技术决策框架" tabindex="-1">技术决策框架 <a class="header-anchor" href="#技术决策框架" aria-label="Permalink to &quot;技术决策框架&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>技术决策的难点通常不是“知道哪些技术”，而是把模糊诉求转换成可审查的约束，用足够的证据比较候选项，并把收益、代价和反悔条件一起写清楚。本章给出一套适用于框架、架构、工具和服务采购的通用决策框架；具体技术的基础用法仍由核心知识和工程体系负责。</p><h2 id="_1-决策对象与边界" tabindex="-1">1. 决策对象与边界 <a class="header-anchor" href="#_1-决策对象与边界" aria-label="Permalink to &quot;1. 决策对象与边界&quot;">​</a></h2><h3 id="_1-1-什么值得进入正式决策" tabindex="-1">1.1 什么值得进入正式决策 <a class="header-anchor" href="#_1-1-什么值得进入正式决策" aria-label="Permalink to &quot;1.1 什么值得进入正式决策&quot;">​</a></h3><p>当选择具有以下任一特征时，值得形成书面决策：</p><ul><li>会改变跨模块接口、部署拓扑或数据所有权；</li><li>需要多个团队共同迁移，或者退出成本明显高于试用成本；</li><li>涉及安全、隐私、许可证、监管或供应商合同；</li><li>会持续产生基础设施费用、维护责任或人员能力要求；</li><li>团队存在实质分歧，并且结论需要在数月后仍可解释。</li></ul><p>局部、可逆、低成本的实现细节不必套用完整流程。它们更适合用短期实验、代码评审或团队约定解决。</p><h3 id="_1-2-决策陈述必须可比较" tabindex="-1">1.2 决策陈述必须可比较 <a class="header-anchor" href="#_1-2-决策陈述必须可比较" aria-label="Permalink to &quot;1.2 决策陈述必须可比较&quot;">​</a></h3><p>“选择最先进的框架”不是决策问题，因为“先进”无法验证。可用的陈述应包含对象、范围、目标和时限：</p><blockquote><p>为 2026 年启动、由 8 名 Vue 工程师维护的内部运营后台选择 UI 框架；首期需要在 12 周内交付，并支持未来三年的表单、表格和权限页面维护。</p></blockquote><p>这个陈述排除了移动端、营销站和全栈运行时，后续比较才能围绕同一个问题展开。</p><h3 id="_1-3-明确负责人和有效范围" tabindex="-1">1.3 明确负责人和有效范围 <a class="header-anchor" href="#_1-3-明确负责人和有效范围" aria-label="Permalink to &quot;1.3 明确负责人和有效范围&quot;">​</a></h3><p>负责人负责收集证据、推动结论和发起复查，但不等于独自决定。记录中至少写明：</p><table tabindex="0"><thead><tr><th>字段</th><th>示例</th></tr></thead><tbody><tr><td>决策负责人</td><td>前端架构负责人</td></tr><tr><td>参与者</td><td>业务前端、设计系统、测试、运维</td></tr><tr><td>影响范围</td><td>新运营后台，不追溯迁移旧系统</td></tr><tr><td>最晚决定时间</td><td>2026-08-20</td></tr><tr><td>预期有效期</td><td>首期上线后 12 个月内</td></tr></tbody></table><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-先用硬约束淘汰候选" tabindex="-1">2.1 先用硬约束淘汰候选 <a class="header-anchor" href="#_2-1-先用硬约束淘汰候选" aria-label="Permalink to &quot;2.1 先用硬约束淘汰候选&quot;">​</a></h3><p>硬约束是不满足就不能采用的条件，不能参与加权平均。常见来源包括：</p><ul><li>浏览器、设备、Node.js 版本和部署平台的最低基线；</li><li>数据驻留、隐私、许可证和采购合同；</li><li>已承诺的上线日期和不可变更的外部协议；</li><li>安全边界、无障碍等级和灾难恢复要求。</li></ul><p>如果某方案违反硬约束，就应淘汰或先消除冲突。不能因为它“开发体验好”而继续用评分补偿。</p><h3 id="_2-2-再比较可权衡标准" tabindex="-1">2.2 再比较可权衡标准 <a class="header-anchor" href="#_2-2-再比较可权衡标准" aria-label="Permalink to &quot;2.2 再比较可权衡标准&quot;">​</a></h3><p>评价标准描述方案之间允许取舍的差异。每项标准都要定义观察方法，而不是只写抽象名词。</p><table tabindex="0"><thead><tr><th>标准</th><th>可观察定义</th><th style="text-align:right;">权重示例</th></tr></thead><tbody><tr><td>首期交付</td><td>完成登录、权限、表格和表单基线所需人周</td><td style="text-align:right;">30%</td></tr><tr><td>团队能力</td><td>能独立评审和排障的人数，而非“听说过”的人数</td><td style="text-align:right;">25%</td></tr><tr><td>生态适配</td><td>关键组件、测试和监控是否已有稳定集成</td><td style="text-align:right;">20%</td></tr><tr><td>长期维护</td><td>升级频率、破坏性变更和内部封装成本</td><td style="text-align:right;">15%</td></tr><tr><td>退出成本</td><td>页面、组件和领域代码可迁移程度</td><td style="text-align:right;">10%</td></tr></tbody></table><p>权重不是精确数学事实，而是把真实优先级暴露出来。若团队无法接受权重变化带来的结论变化，说明预设答案仍未被揭示。</p><h3 id="_2-3-区分事实、估计和假设" tabindex="-1">2.3 区分事实、估计和假设 <a class="header-anchor" href="#_2-3-区分事实、估计和假设" aria-label="Permalink to &quot;2.3 区分事实、估计和假设&quot;">​</a></h3><p>所有证据应标记可信度：</p><ul><li><strong>事实</strong>：官方支持范围、许可证、实测构建结果、历史故障数据；</li><li><strong>估计</strong>：基于已知工作量推算的迁移成本，应给出区间；</li><li><strong>假设</strong>：尚未验证的团队学习速度、未来业务规模或供应商承诺。</li></ul><p>影响大且置信度低的假设，应优先通过原型或限量试点验证。</p><h2 id="_3-候选方案与证据" tabindex="-1">3. 候选方案与证据 <a class="header-anchor" href="#_3-候选方案与证据" aria-label="Permalink to &quot;3. 候选方案与证据&quot;">​</a></h2><h3 id="_3-1-保留现状也是候选项" tabindex="-1">3.1 保留现状也是候选项 <a class="header-anchor" href="#_3-1-保留现状也是候选项" aria-label="Permalink to &quot;3.1 保留现状也是候选项&quot;">​</a></h3><p>至少列出“维持现状”和一个真实替代方案。若维持现状有明确成本，也要量化，而不是默认它免费。候选过多会稀释验证资源，通常先用硬约束缩小到二至四项。</p><h3 id="_3-2-用最小实验验证关键未知量" tabindex="-1">3.2 用最小实验验证关键未知量 <a class="header-anchor" href="#_3-2-用最小实验验证关键未知量" aria-label="Permalink to &quot;3.2 用最小实验验证关键未知量&quot;">​</a></h3><p>原型不是做一遍完整项目，而是验证最可能改变结论的问题。例如框架选型可以只实现：</p><ul><li>一个包含异步校验的复杂表单；</li><li>一个 5 万行数据的虚拟表格；</li><li>路由权限、错误监控和组件测试各一条完整链路；</li><li>生产构建并记录产物、冷启动和调试体验。</li></ul><p>实验开始前要写出成功阈值。否则团队很容易在看到结果后移动标准。</p><h3 id="_3-3-不把流行度当成替代证据" tabindex="-1">3.3 不把流行度当成替代证据 <a class="header-anchor" href="#_3-3-不把流行度当成替代证据" aria-label="Permalink to &quot;3.3 不把流行度当成替代证据&quot;">​</a></h3><p>下载量、社区声量和招聘数量只能说明生态信号，不能直接证明方案适合当前约束。关键结论应来自官方能力边界、团队试验、现有系统数据或可追溯的行业案例。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>下面是运营后台 UI 框架的已填写比较。硬约束检查已经确认两项都满足公司许可证、安全和浏览器基线。</p><table tabindex="0"><thead><tr><th>维度</th><th>Vue 3</th><th>React 19</th><th>证据</th></tr></thead><tbody><tr><td>首期交付</td><td>8 人中 7 人可直接开发</td><td>8 人中 2 人有生产经验</td><td>人员技能盘点、两周原型</td></tr><tr><td>组件生态</td><td>现有 Vue 组件库可复用 82%</td><td>需要适配或替换主要组件</td><td>组件清单与迁移试验</td></tr><tr><td>复杂交互</td><td>满足表格、表单和图表需求</td><td>同样满足</td><td>原型验收结果</td></tr><tr><td>长期招聘</td><td>本地人才充足</td><td>候选人更多，但不是当前瓶颈</td><td>过去一年招聘数据</td></tr><tr><td>退出成本</td><td>领域层保持纯 TypeScript，可控</td><td>领域层同样可隔离</td><td>架构草图和示例模块</td></tr></tbody></table><p>在这个案例中，两者能力都足够，差异主要来自团队和既有资产。继续争论抽象的框架优劣不会提高决策质量。</p><h2 id="_5-推荐结论与置信度" tabindex="-1">5. 推荐结论与置信度 <a class="header-anchor" href="#_5-推荐结论与置信度" aria-label="Permalink to &quot;5. 推荐结论与置信度&quot;">​</a></h2><p>推荐结论应同时回答“选什么”“为什么”“在什么范围内”和“还有什么未知量”：</p><blockquote><p>新运营后台采用 Vue 3。决定只适用于该后台，不要求其他产品迁移。主要依据是首期交付和现有组件资产，结论置信度为高。React 19 的生态规模不是当前约束，因此不构成反转理由。</p></blockquote><p>当关键证据仍不足时，可以做有时限的试点决定，而不是假装已经得到永久结论。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><h3 id="_6-1-接受的收益与代价" tabindex="-1">6.1 接受的收益与代价 <a class="header-anchor" href="#_6-1-接受的收益与代价" aria-label="Permalink to &quot;6.1 接受的收益与代价&quot;">​</a></h3><p>选择 Vue 3 后，团队获得更短的首期交付时间和组件复用；同时接受跨 React 团队共享 UI 代码更困难、需要继续维护 Vue 能力梯队等后果。只有写出负面后果，记录才真正表达了取舍。</p><h3 id="_6-2-把退出成本设计进方案" tabindex="-1">6.2 把退出成本设计进方案 <a class="header-anchor" href="#_6-2-把退出成本设计进方案" aria-label="Permalink to &quot;6.2 把退出成本设计进方案&quot;">​</a></h3><p>退出路径不是承诺将来一定迁移，而是避免无意制造锁定：</p><ul><li>领域规则和 API 客户端保持框架无关；</li><li>组件库公开稳定的设计令牌和交互契约；</li><li>不把核心数据模型塞入组件实例；</li><li>每年估算一次升级和替换成本。</li></ul><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><p>完整框架不适用于紧急故障处置、单文件内部实现和几小时可撤销的试验。对于安全或合规硬要求，也不应通过评分表“决定是否遵守”；团队只能比较满足要求的实现方式。</p><h2 id="_8-填写完成的决策摘要" tabindex="-1">8. 填写完成的决策摘要 <a class="header-anchor" href="#_8-填写完成的决策摘要" aria-label="Permalink to &quot;8. 填写完成的决策摘要&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>已填写内容</th></tr></thead><tbody><tr><td>问题</td><td>为新运营后台选择 UI 框架</td></tr><tr><td>硬约束</td><td>12 周上线；支持公司浏览器基线；复用现有权限和监控；许可证合规</td></tr><tr><td>候选</td><td>Vue 3、React 19、维持旧 Vue 2 脚手架</td></tr><tr><td>淘汰项</td><td>Vue 2：已停止用于新项目，无法满足三年维护策略</td></tr><tr><td>决定</td><td>Vue 3，仅覆盖新后台</td></tr><tr><td>核心证据</td><td>两周原型、人员盘点、82% 组件复用率</td></tr><tr><td>接受后果</td><td>继续维护 Vue 能力；跨框架 UI 共享受限</td></tr><tr><td>负责人</td><td>前端架构负责人</td></tr><tr><td>复查时间</td><td>首期上线后 3 个月</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>以下任一条件发生时重新评估，而不是等固定日期机械开会：</p><ul><li>首期交付估算偏差超过 30%；</li><li>关键组件无法满足性能或无障碍要求；</li><li>Vue 熟练维护者低于 3 人且连续两个季度无法补充；</li><li>框架或核心生态进入停止维护状态；</li><li>产品范围扩展到需要跨多个技术栈共享运行时代码。</li></ul><p>好的决策不是一次选中“正确答案”，而是让当时的结论有证据、后果可见，并能在前提变化时被低成本修正。</p>',59)])])}const b=a(l,[["render",i]]);export{p as __pageData,b as default};
